package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
class StudyPhenotypeGseaTest {
    @TempDir Path root;
    private Map<String,Object> external() throws Exception {
        Files.writeString(root.resolve("ranks.tsv"),"gene_id\tstatistic\nA\t4\nB\t3\nC\t-1\nD\t-2\n");Files.writeString(root.resolve("sets.gmt"),"top\tSynthetic top\tA\tB\nbottom\tSynthetic bottom\tC\tD\n");
        Files.writeString(root.resolve("null.tsv"),"draw_id\tgene_id\tstatistic\nx\tA\t4\nx\tB\t3\nx\tC\t-1\nx\tD\t-2\ny\tD\t2\ny\tC\t1\ny\tB\t-3\ny\tA\t-4\n");
        var p=new LinkedHashMap<String,Object>(Map.of("ranking",Map.of("file","ranks.tsv","coverage","complete","tested_genes",4),"gene_sets","sets.gmt","species","human","minimum_size",2,"maximum_size",2,"null_model","phenotype","curve_plots",0));
        p.put("null_rankings",new LinkedHashMap<String,Object>(Map.of("file","null.tsv","draws",2,"coverage","complete","sampling","monte_carlo","observed_sha256",FollowupSupport.hash(root.resolve("ranks.tsv")),"method","Synthetic shared draws","model","External registered model","exchangeability","Synthetic independent null draws","provenance",Map.of("producer","fixture"))));return p;
    }
    private Context context(String id,Map<String,Object> p) throws Exception{return new Context(root,Files.createDirectory(root.resolve(id)),Map.of("id",id,"type","ranked_gsea","hypothesis","H","datasets",List.of()),Map.of("datasets",List.of(),"resources",Map.of("network","offline","downloads","deny"),"hypotheses",List.of(Map.of("id","H","analysis",Map.of("gsea",p)))),Map.of(),Map.of());}
    @Test void importedJointNullNeedsNoParticipantsAndProducesCanonicalResults() throws Exception {var p=external();var c=context("external",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());var table=DelimitedData.readResult(c.outputDirectory().resolve("ranked-gsea.tsv"));assertEquals(2,table.rows().size());for(var row:table.rows()){assertEquals("supplied_monte_carlo_model_null",row[table.column("null_method")]);assertEquals(1,Double.parseDouble(row[table.column("p_value")]),0);}assertEquals("supplied_complete_model_matched_ensemble_not_refitted",result.details().get("null_rankings_source"));assertTrue(String.valueOf(result.details().get("required_manuscript_caveat")).contains("source declarations"));}
    @Test void exactObservedFileBindingIsRequired() throws Exception{var p=external();Files.writeString(root.resolve("ranks.tsv"),Files.readString(root.resolve("ranks.tsv")).replace("A\t4","A\t5"));var c=context("changed",p);var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertTrue(result.summary().contains("observed_sha256"));assertFalse(Files.exists(c.outputDirectory().resolve("ranked-gsea.tsv")));}
    @Test void extraMissingAndWrongUniverseDrawsCannotPublishAPartialFamily() throws Exception {var p=external();String original=Files.readString(root.resolve("null.tsv"));String[] bad={original+"z\tA\t1\n",original.replace("y\tA\t-4\n",""),original.replace("y\tA\t-4","y\tX\t-4"),original.replace("y\tA\t-4","y\tB\t-4")};for(int i=0;i<bad.length;i++){Files.writeString(root.resolve("null.tsv"),bad[i]);var c=context("bad-"+i,p);var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state(),result.summary());assertFalse(Files.exists(c.outputDirectory().resolve("ranked-gsea.tsv")));}}
    @Test void nullFileContentsEnterCacheIdentity() throws Exception {var p=external();var c=context("hash",p);var before=StudyGseaResources.inputHashes(root,c.study(),c.operation());Files.writeString(root.resolve("null.tsv"),Files.readString(root.resolve("null.tsv")).replace("y\tD\t2","y\tD\t3"));var after=StudyGseaResources.inputHashes(root,c.study(),c.operation());assertNotEquals(before.get("gsea:null_rankings"),after.get("gsea:null_rankings"));assertEquals(before.get("gsea:ranking"),after.get("gsea:ranking"));}
    @Test void nullDrawBlocksMustNotReappearOrIncludeUnknownPolicyFields() throws Exception {var p=external();Files.writeString(root.resolve("null.tsv"),Files.readString(root.resolve("null.tsv")).replace("y\tD","x\tD").replace("y\tC","x\tC").replace("y\tB","x\tB").replace("y\tA","x\tA"));assertEquals(State.WAITING_FOR_INPUT,new StudyCliExecutor().execute(context("blocks",p)).state());StudyPublicEvidence.map(p.get("null_rankings"));var bad=new LinkedHashMap<>(StudyPublicEvidence.map(p.get("null_rankings")));bad.put("top_draws",1);p.put("null_rankings",bad);assertThrows(IllegalArgumentException.class,()->org.jlinalg.study.StudyGseaPolicy.resolve(p));}
    private Map<String,Object> nativeStudy() throws Exception {
        StringBuilder pheno=new StringBuilder("id\ttrait\tage\tsex\n"),matrix=new StringBuilder("feature_id");for(int i=0;i<14;i++){matrix.append("\ts").append(i);pheno.append("s").append(i).append('\t').append(2+i*.13+Math.sin(i*.8)).append('\t').append(20+i+(i%3)*.7).append('\t').append(i%2==0?"F":"M").append('\n');}matrix.append('\n');for(int j=0;j<6;j++){matrix.append((char)('A'+j));for(int i=0;i<14;i++)matrix.append('\t').append(j==5&&i==2?"NA":String.valueOf(Math.sin(i*(.2+j*.17))+Math.cos(i*.33+j)*.4+j*.1));matrix.append('\n');}Files.writeString(root.resolve("matrix.tsv"),matrix);Files.writeString(root.resolve("pheno.tsv"),pheno);Files.writeString(root.resolve("sets.gmt"),"one\tOne\tA\tB\tC\nsecond\tSecond\tD\tE\tF\n");
        var gsea=new LinkedHashMap<String,Object>(Map.of("null_model","phenotype","phenotype",new LinkedHashMap<>(Map.of("independent_samples",true,"exchangeable_errors",true,"strata_column","sex")),"gene_sets","sets.gmt","minimum_size",2,"maximum_size",4,"maximum_exact_states",0,"permutations",31,"seed",9,"curve_plots",0));
        var analysis=new LinkedHashMap<String,Object>(Map.of("mode","manual","goals",List.of("ranked_gsea"),"association",new LinkedHashMap<>(Map.of("model","ols","family","gaussian")),"gsea",gsea));
        return new LinkedHashMap<>(Map.of("schema_version",1,"project",Map.of("id","native-gsea","title","Native phenotype fixture","description","Synthetic independent OLS"),"resources",Map.of("directory","fixture-resources","network","offline","downloads","deny"),"cohorts",List.of(Map.of("id","A")),"datasets",List.of(Map.of("id","d","cohort","A","type","expression","stage","processed_matrix","species","human","feature_id_type","gene_symbol","files",Map.of("matrix","matrix.tsv","phenotype","pheno.tsv"))),"hypotheses",List.of(Map.of("id","H","description","Native null","outcome","trait","covariates",List.of("age","sex"),"analysis",analysis))));
    }
    @SuppressWarnings("unchecked")
    private Map<String,Object> analysis(Map<String,Object> study){return (Map<String,Object>)((Map<?,?>)((List<?>)study.get("hypotheses")).get(0)).get("analysis");}
    private List<Map<String,Object>> run(Map<String,Object> study) throws Exception{Path input=root.resolve("study.json");StudyPublicEvidence.write(input,study);var err=new ByteArrayOutputStream();assertEquals(0,JLinAlgCli.run(new String[]{"study","auto",input.toString(),"--offline","--actor-type","external","--actor-id","fixture"},new PrintStream(new ByteArrayOutputStream()),new PrintStream(err)),err.toString());var status=StudyYaml.loadArtifact(root.resolve("state/project-status.yaml"));var manifests=new ArrayList<Map<String,Object>>();try(var paths=Files.walk(root.resolve("runs").resolve(String.valueOf(status.get("run_id"))).resolve("operations"))){for(Path path:paths.filter(f->f.getFileName().toString().equals("manifest.yaml")).toList()){var m=StudyYaml.loadArtifact(path);m.put("_directory",path.getParent());manifests.add(m);}}return manifests;}
    @SuppressWarnings("unchecked")
    @Test void nativeOnlyGoalPlansParticipantQcRefitsAllGenesAndReusesCompletedWork() throws Exception {var study=nativeStudy();String matrixHash=FollowupSupport.hash(root.resolve("matrix.tsv"));var manifests=run(study);var gsea=manifests.stream().filter(m->m.get("operation_type").equals("ranked_gsea")).findFirst().orElseThrow();assertEquals("complete",gsea.get("state"),gsea.toString());assertFalse(manifests.stream().anyMatch(m->m.get("operation_type").equals("association")));assertTrue(manifests.stream().anyMatch(m->m.get("operation_type").equals("participant_qc")));var details=StudyPublicEvidence.map(gsea.get("details"));assertEquals(14,details.get("analysis_samples"));assertEquals(10,details.get("residual_df"));assertEquals("native_refit",details.get("null_rankings_source"));assertEquals(false,details.get("source_FDR_filter_applied"));Path dir=(Path)gsea.get("_directory");assertEquals(6,DelimitedData.readResult(dir.resolve("ranked-genes.tsv")).rows().size());assertEquals(31*6,DelimitedData.readResult(dir.resolve("null-rankings.tsv")).rows().size());assertEquals(matrixHash,FollowupSupport.hash(root.resolve("matrix.tsv")));for(var m:run(study))assertEquals(true,m.get("reused_from_cache"),m.toString());}
    @Test void independentDeclarationsAndUnsupportedFamiliesHoldWithoutFallback() throws Exception {var study=nativeStudy();var a=analysis(study);var gsea=StudyPublicEvidence.map(a.get("gsea"));var phenotype=StudyPublicEvidence.map(gsea.get("phenotype"));phenotype.put("exchangeable_errors",false);gsea.put("phenotype",phenotype);a.put("gsea",gsea);var manifests=run(study);var result=manifests.stream().filter(m->m.get("operation_type").equals("ranked_gsea")).findFirst().orElseThrow();assertEquals("waiting_for_input",result.get("state"));assertTrue(String.valueOf(result.get("summary")).contains("exchangeable_errors")||String.valueOf(result.get("details")).contains("exchangeable_errors"));}
    @Test void nativeAndExternalContractsCannotBeMixed() throws Exception {var p=external();p.put("phenotype",Map.of("independent_samples",true));assertThrows(IllegalArgumentException.class,()->org.jlinalg.study.StudyGseaPolicy.resolve(p));p.remove("phenotype");p.put("null_model","gene_set");assertThrows(IllegalArgumentException.class,()->org.jlinalg.study.StudyGseaPolicy.resolve(p));}
    @Test void unsupportedNativeModelsDoNotBecomeUnadjustedLabelShuffles() throws Exception {
        var study=nativeStudy();var a=analysis(study);int i=0;
        for(var model:List.of(Map.of("model","glm","family","binomial"),Map.of("model","lmm"),Map.of("model","ols","offset_column","age"))){a.put("association",model);var c=new Context(root,Files.createDirectory(root.resolve("unsupported-"+i++)),Map.of("id","test","type","ranked_gsea","hypothesis","H","dataset_id","d","datasets",List.of("d")),study,Map.of(),Map.of());var result=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertTrue(result.summary().contains("independent Gaussian"));assertFalse(Files.exists(c.outputDirectory().resolve("ranked-gsea.tsv")));}
    }
    @Test void nativeCohortsHaveDistinctQcPopulationsAndNullOperations() throws Exception {
        var study=nativeStudy();var first=StudyPublicEvidence.map(((List<?>)study.get("datasets")).get(0));var second=new LinkedHashMap<>(first);second.put("id","e");second.put("cohort","B");study.put("datasets",List.of(first,second));study.put("cohorts",List.of(Map.of("id","A"),Map.of("id","B")));Path input=root.resolve("multi.json");StudyPublicEvidence.write(input,study);
        var plan=org.jlinalg.study.StudyPlanner.compile(org.jlinalg.study.StudyResolver.resolve(input));var ops=StudyPublicEvidence.list(plan.document().get("operations")).stream().map(StudyPublicEvidence::map).toList();var gsea=ops.stream().filter(op->"ranked_gsea".equals(op.get("type"))).toList();assertEquals(2,gsea.size());for(var op:gsea){var qc=ops.stream().filter(prior->prior.get("id").equals(op.get("participant_qc_producer"))).findFirst().orElseThrow();assertEquals("participant_qc",qc.get("type"));assertEquals(op.get("dataset_id"),qc.get("dataset_id"));assertTrue(StudyPublicEvidence.list(op.get("depends_on")).contains(qc.get("id")));}
    }
}
